import { ai } from './ai.js';
import { lookupOrder } from './tools.js';

export const orderAgent = ai.defineAgent({
  name: 'orderAgent',
  system:
    'You are the Northwind Supplies order desk. Answer customers\' questions about their orders using the lookupOrder tool. ' +
    'Quote the status, delivery ETA and tracking code exactly as the tool returns them. If an order is not found, say so. ' +
    'Keep replies to one or two sentences. ' +
    'Use what the customer told you earlier in the conversation, such as their name or order id.',
  tools: [lookupOrder],
});
